import{_ as t,c as a,o as n,al as s}from"./chunks/framework.DM883ANZ.js";const u=JSON.parse('{"title":"Events Interface","description":"Events Interface — MAVLink message, enum and command reference.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Events Interface"}],["meta",{"property":"og:description","content":"Events Interface — MAVLink message, enum and command reference."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://mavlink.io/en/services/events.html"}],["link",{"rel":"canonical","href":"https://mavlink.io/en/services/events.html"}]]},"headers":[],"relativePath":"en/services/events.md","filePath":"en/services/events.md","lastUpdated":1790825395000}'),o={name:"en/services/events.md"};function r(i,e,l,c,d,h){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="events-interface" tabindex="-1">Events Interface <a class="header-anchor" href="#events-interface" aria-label="Permalink to &quot;Events Interface&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Events Interface is implemented in PX4 and QGroundControl.</p></div><p>The <em>Events Interface</em> is a generic and flexible mechanism that allows one component to reliably notify a GCS (or any other component) of sporadic events and state changes. For example, the interface might be used notifying of arming readiness, calibration completion, and reaching the target takeoff height.</p><p>The interface provides for both common events that are shared by flight stacks or other components, and events that are specific to an implementation. MAVLink &quot;common&quot; events are defined in <a href="https://github.com/mavlink/libevents/blob/main/events/common.json" target="_blank" rel="noreferrer">mavlink/libevents/events/common.json</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The events interface is intended to replace the widespread use of <a href="./../messages/common.html#STATUSTEXT">STATUSTEXT</a> messages.</p></div><h2 id="key-features" tabindex="-1">Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;">​</a></h2><p>The following key features are provided by the interface:</p><ul><li>Reliable delivery with retransmission.</li><li>Consistent interface to report system health and arming checks.</li><li>Minimized buffer requirements on the autopilot side.</li><li>Minimized binary message length.</li><li>Generic: autopilot- and GCS-agnostic.</li><li>Long-term stable and extensible.</li><li>Allows arguments to be attached to an event.</li><li>Possible types: <code>uint8</code>, <code>int8</code>, <code>uint16</code>, <code>int16</code>, <code>uint32</code>, <code>int32</code>, <code>int64</code>, <code>uint64</code>, <code>float</code>.</li><li>Enums and bit fields can be built on top of these types</li><li>Enable automated processing (for example from a flight log containing events).</li><li>Minimize amount of auto-generated code for embedded implementations.</li><li>Events volume of &lt;1 Hz on average (may scale with protocol parameters adjustments, like retransmission timeouts).</li><li>Events can be targeted or broadcast</li><li>Any component can send events, including cameras, companion computers, ground stations, etc.</li><li>Events have metadata, like a log level. They can also have a detailed, more extensive description, possibly with URLs.</li><li>Support for message text and message translation.</li></ul><h2 id="message-enum-summary" tabindex="-1">Message/Enum Summary <a class="header-anchor" href="#message-enum-summary" aria-label="Permalink to &quot;Message/Enum Summary&quot;">​</a></h2><h3 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Description</th></tr></thead><tbody><tr><td><a id="EVENT"></a><a href="./../messages/common.html#EVENT">EVENT</a></td><td>Event message. Each new event from a particular component gets a new sequence number. The same message might be sent multiple times if (re-)requested. Most events are broadcast, some can be specific to a target component (as receivers keep track of the sequence for missed events, all events need to be broadcast. Thus we use destination_component instead of target_component).</td></tr><tr><td><a id="CURRENT_EVENT_SEQUENCE"></a><a href="./../messages/common.html#CURRENT_EVENT_SEQUENCE">CURRENT_EVENT_SEQUENCE</a></td><td>Regular broadcast for the current latest event sequence number for a component. This is used to check for dropped events.</td></tr><tr><td><a id="REQUEST_EVENT"></a><a href="./../messages/common.html#REQUEST_EVENT">REQUEST_EVENT</a></td><td>Request one or more events to be (re-)sent. If <code>first_sequence==last_sequence</code>, only a single event is requested. Note that <code>first_sequence</code>can be larger than<code>last_sequence</code> (because the sequence number can wrap). Each sequence will trigger an <a href="#EVENT">EVENT</a> or <a href="#RESPONSE_EVENT_ERROR">RESPONSE_EVENT_ERROR</a> response.</td></tr><tr><td><a id="RESPONSE_EVENT_ERROR"></a><a href="./../messages/common.html#RESPONSE_EVENT_ERROR">RESPONSE_EVENT_ERROR</a></td><td>Response to a <a href="#REQUEST_EVENT">REQUEST_EVENT</a> if there is an error requesting an event, including the reason. The most common reason would be that the event is not longer available (has been discarded).</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Enum</th><th>Description</th></tr></thead><tbody><tr><td><a id="MAV_EVENT_CURRENT_SEQUENCE_FLAGS"></a><a href="./../messages/common.html#MAV_EVENT_CURRENT_SEQUENCE_FLAGS">MAV_EVENT_CURRENT_SEQUENCE_FLAGS</a></td><td>Flags for <a href="#CURRENT_EVENT_SEQUENCE">CURRENT_EVENT_SEQUENCE</a>. For example, to indicate when the sequence has reset.</td></tr><tr><td><a id="MAV_EVENT_ERROR_REASON"></a><a href="./../messages/common.html#MAV_EVENT_ERROR_REASON">MAV_EVENT_ERROR_REASON</a></td><td>Reasons for an error, as provided in <a href="#RESPONSE_EVENT_ERROR">RESPONSE_EVENT_ERROR</a>. For example, common error would be that the event is not available (i.e. it has been discarded).</td></tr></tbody></table><h2 id="event-definitions-and-metadata" tabindex="-1">Event Definitions and Metadata <a class="header-anchor" href="#event-definitions-and-metadata" aria-label="Permalink to &quot;Event Definitions and Metadata&quot;">​</a></h2><p>Each event is identified by a 32-bit ID (<a href="./../messages/common.html#EVENT">EVENT.id</a>). The most significant 8 bits are the component ID of the namespace that defines the event (typically the MAVLink component ID of the sender), and the lower 24 bits identify the event within that namespace. Events shared by multiple flight stacks and components are defined in the libevents <code>common</code> namespace (<a href="https://github.com/mavlink/libevents/blob/main/events/common.json" target="_blank" rel="noreferrer">common.json</a>).</p><p>The <a href="#EVENT">EVENT</a> message only contains the event ID, a timestamp, the log levels, and the event arguments. All other information about the event, such as its name, message text, description, and argument types, is defined in JSON metadata that conforms to the <a href="https://github.com/mavlink/libevents/blob/main/validation/schema.json" target="_blank" rel="noreferrer">libevents schema</a>. A receiver fetches this metadata, and combines it with the event ID and arguments in order to display or process the event. As the metadata is not in the message, the event text can be translated, and can be much longer than would fit in a <a href="./../messages/common.html#STATUSTEXT">STATUSTEXT</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <a href="./component_metadata.html">Component Metadata Protocol</a> (<a href="./../messages/common.html#COMP_METADATA_TYPE_EVENTS">COMP_METADATA_TYPE_EVENTS</a>) should be used to get the metadata. This ensures the event ids and their metadata are kept synchronised.</p></div><p>The metadata for each event includes:</p><ul><li>A short, single-line message, and an optional longer description. These may contain argument placeholders, URLs, and parameter links (see the <a href="https://github.com/mavlink/libevents/blob/main/README.md" target="_blank" rel="noreferrer">libevents README</a> for the format).</li><li>Arguments. Valid types are: <code>uint8_t</code>, <code>int8_t</code>, <code>uint16_t</code>, <code>int16_t</code>, <code>uint32_t</code>, <code>int32_t</code>, <code>uint64_t</code>, <code>int64_t</code> and <code>float</code>, and enums and bitmasks based on the integer types. Arguments are serialized into <a href="./../messages/common.html#EVENT">EVENT.arguments</a> in the order they are defined, in little-endian byte order and without padding, up to a total of 40 bytes.</li><li>A group, which a GCS can use to handle a set of events differently. Groups include <code>default</code>, <code>calibration</code>, <code>health</code> and <code>arming_check</code>. A GCS should not display events from groups that it does not recognise.</li></ul><p>Each event has two log levels, which are sent in <a href="./../messages/common.html#EVENT">EVENT.log_levels</a>: an external log level (4 least significant bits) that is used by a GCS, and an internal log level (4 most significant bits) that is used for logging. The values are the same as <a href="./../messages/common.html#MAV_SEVERITY">MAV_SEVERITY</a>, with the addition of <code>Protocol</code> (8) for events that should not be displayed to users, and <code>Disabled</code> (9).</p><h2 id="sending-events" tabindex="-1">Sending Events <a class="header-anchor" href="#sending-events" aria-label="Permalink to &quot;Sending Events&quot;">​</a></h2><p>A component that sends events must:</p><ul><li><p>Assign each new event the next sequence number. The sequence number is a <code>uint16_t</code> that wraps back to 0 after 65535.</p></li><li><p>Send each new event in an <a href="#EVENT">EVENT</a> message. Events are usually broadcast (<code>destination_system</code> is 0 and <code>destination_component</code> is <a href="./../messages/common.html#MAV_COMP_ID_ALL">MAV_COMP_ID_ALL</a>). An event can be addressed to a particular component by setting the destination fields, but other receivers still use its sequence number to detect lost events.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="#EVENT">EVENT</a> uses <code>destination_system</code> and <code>destination_component</code> for addressing, instead of the usual <code>target_system</code>/<code>target_component</code> fields. This ensures that <code>EVENT</code> messages are routed as a broadcast message and that every receiver gets to see every event and can minimally process it to track the sequence number.</p></div></li><li><p>Keep a buffer of the most recently sent events, so that they can be re-sent if requested.</p></li><li><p>Broadcast <a href="#CURRENT_EVENT_SEQUENCE">CURRENT_EVENT_SEQUENCE</a> with the latest sequence number at a regular interval (nominally every 3 seconds). This allows receivers to detect lost events even if no new events are sent.</p></li><li><p>Set the <a href="./../messages/common.html#MAV_EVENT_CURRENT_SEQUENCE_FLAGS_RESET">MAV_EVENT_CURRENT_SEQUENCE_FLAGS_RESET</a> flag in <code>CURRENT_EVENT_SEQUENCE</code> if the sequence number has been reset (for example, after a reboot).</p></li><li><p>Respond to a <a href="#REQUEST_EVENT">REQUEST_EVENT</a> by handling each sequence number from <code>first_sequence</code> to <code>last_sequence</code> (the range may wrap):</p><ul><li>If the event is still in the buffer, re-send it in an <code>EVENT</code> message.</li><li>Otherwise, send a <a href="#RESPONSE_EVENT_ERROR">RESPONSE_EVENT_ERROR</a> addressed to the requester, with <code>sequence</code> set to the requested sequence number, <code>reason</code> set to <a href="./../messages/common.html#MAV_EVENT_ERROR_REASON_UNAVAILABLE">MAV_EVENT_ERROR_REASON_UNAVAILABLE</a>, and <code>sequence_oldest_available</code> set to the oldest buffered sequence number after the requested one.</li></ul></li></ul><p>The sender does not need to track receivers, or know whether an event has been received.</p><h2 id="receiving-events" tabindex="-1">Receiving Events <a class="header-anchor" href="#receiving-events" aria-label="Permalink to &quot;Receiving Events&quot;">​</a></h2><p>A component that receives events tracks the latest received sequence number separately for each sender (system ID and component ID), and must:</p><ul><li>Initialise the latest received sequence number from the first <code>EVENT</code> or <code>CURRENT_EVENT_SEQUENCE</code> received from the sender.</li><li>For each <code>EVENT</code>: <ul><li>If the sequence number is the next expected one, process the event and update the latest received sequence number.</li><li>If the sequence number is older than the latest received, discard the event (it is a duplicate).</li><li>If the sequence number is newer than the next expected one, events have been lost: request the missing events using <code>REQUEST_EVENT</code>.</li></ul></li><li>For each <code>CURRENT_EVENT_SEQUENCE</code>: <ul><li>If <code>MAV_EVENT_CURRENT_SEQUENCE_FLAGS_RESET</code> is set, discard the tracked sequence state and re-initialise the latest received sequence number from the message.</li><li>If the sequence number is newer than the latest received, request the missing events using <code>REQUEST_EVENT</code>.</li></ul></li><li>Re-send <code>REQUEST_EVENT</code> if the requested events are not received within a timeout (nominally 100 ms).</li><li>On receiving a <code>RESPONSE_EVENT_ERROR</code> for a requested event, treat the events from the requested sequence up to (but not including) <code>sequence_oldest_available</code> as lost, and continue from <code>sequence_oldest_available</code>.</li><li>Only act on events where <code>destination_system</code> is 0 or its own system ID, and <code>destination_component</code> is <code>MAV_COMP_ID_ALL</code> or its own component ID.</li></ul><p>All sequence number comparisons must handle wrap-around.</p><p>A receiver that has not yet downloaded the metadata for a sender can only identify events by ID. It should either queue events until the metadata is available, or discard them.</p><h2 id="sequences" tabindex="-1">Sequences <a class="header-anchor" href="#sequences" aria-label="Permalink to &quot;Sequences&quot;">​</a></h2><h3 id="event-delivery" tabindex="-1">Event Delivery <a class="header-anchor" href="#event-delivery" aria-label="Permalink to &quot;Event Delivery&quot;">​</a></h3><p>The sender sends each new event with the next sequence number, and regularly broadcasts the latest sequence number.</p><p><a href="https://mermaid.live/edit#pako:eNqtUcFKw0AU_JXHnhKsB68t9lJzNGhiPQll2Z02C81uuvtSLaX_7qNpFBGhB_f0dt7Mm4E5KhMs1JRUwq6HN3hwehN1O3vzJK_TkZ1xnfZMFQzcHvH3poa3Iz7Mt_P5SJ9S8VqUL9locO_zgTkSfnCfYjBIibCHHM7w0cEwLI3q_GqXm7t_8CkDg4Iovq5MBmvxk8-B1ngXjQnepj-TLZZVJdlW54SrunheFuWiuDrqo2bTINFWMxJTHBbfUSnzgRvnN8SBbMjVhFSL2Gpnpdij4gbtuWKLte63rE5C0D2H-uCN4Bx7CNJ3Vgwu9V_g0ydvH7kH" target="_blank" rel="noreferrer"><img src="https://mermaid.ink/img/pako:eNqtUcFKw0AU_JXHnhKsB68t9lJzNGhiPQll2Z02C81uuvtSLaX_7qNpFBGhB_f0dt7Mm4E5KhMs1JRUwq6HN3hwehN1O3vzJK_TkZ1xnfZMFQzcHvH3poa3Iz7Mt_P5SJ9S8VqUL9locO_zgTkSfnCfYjBIibCHHM7w0cEwLI3q_GqXm7t_8CkDg4Iovq5MBmvxk8-B1ngXjQnepj-TLZZVJdlW54SrunheFuWiuDrqo2bTINFWMxJTHBbfUSnzgRvnN8SBbMjVhFSL2Gpnpdij4gbtuWKLte63rE5C0D2H-uCN4Bx7CNJ3Vgwu9V_g0ydvH7kH" alt="Mermaid Sequence: Event delivery"></a></p><h3 id="lost-events" tabindex="-1">Lost Events <a class="header-anchor" href="#lost-events" aria-label="Permalink to &quot;Lost Events&quot;">​</a></h3><p>A receiver detects lost events from a gap in the sequence numbers of incoming events, or from <code>CURRENT_EVENT_SEQUENCE</code> (which is needed if the lost event was the last one sent). It requests the missing events with <code>REQUEST_EVENT</code>.</p><p><a href="https://mermaid.live/edit#pako:eNqdU8FqwzAM_RXhU0PTQ5Nbxnrpwm6BJe1Og2BiZTMkTubIpaP03-fMyWgohbQ-GPP0rCc9oRMrGoEsAtbht0FV4Ivkn5rXTx8K7Gm5JlnIliuCFAuUB9TXkQyVGHH3Xm02Iz2C-D1OdotR4Fl5E-bqeJu5XHtQNR3NTr0MhuQjZcJ-5S0IJCwIBSzw2LpXL3P1y4lFkMZv-zjb5U6plLqj_LJAHyo-hQJvfrlr7_7W5vgWXvqWNITQWOJ_f_7YXdJAaTR92RgeUFEHnb1v1rTdp6lVcmbkWW9Nso2nwrP9rzhhR6BduB9D8PAYwusxhHdYG3rMB1ajrrkUdhtOzFpS_-2FwJKbitjZErihJvtRhcVJG7SIaYXtYtiZAT7_AlVhGy8" target="_blank" rel="noreferrer"><img src="https://mermaid.ink/img/pako:eNqdU8FqwzAM_RXhU0PTQ5Nbxnrpwm6BJe1Og2BiZTMkTubIpaP03-fMyWgohbQ-GPP0rCc9oRMrGoEsAtbht0FV4Ivkn5rXTx8K7Gm5JlnIliuCFAuUB9TXkQyVGHH3Xm02Iz2C-D1OdotR4Fl5E-bqeJu5XHtQNR3NTr0MhuQjZcJ-5S0IJCwIBSzw2LpXL3P1y4lFkMZv-zjb5U6plLqj_LJAHyo-hQJvfrlr7_7W5vgWXvqWNITQWOJ_f_7YXdJAaTR92RgeUFEHnb1v1rTdp6lVcmbkWW9Nso2nwrP9rzhhR6BduB9D8PAYwusxhHdYG3rMB1ajrrkUdhtOzFpS_-2FwJKbitjZErihJvtRhcVJG7SIaYXtYtiZAT7_AlVhGy8" alt="Mermaid Sequence: Lost events"></a></p><h3 id="requested-events-unavailable" tabindex="-1">Requested Events Unavailable <a class="header-anchor" href="#requested-events-unavailable" aria-label="Permalink to &quot;Requested Events Unavailable&quot;">​</a></h3><p>If a requested event is no longer buffered, the sender responds with <code>RESPONSE_EVENT_ERROR</code>. The receiver treats the events before <code>sequence_oldest_available</code> as lost, and continues from there.</p><p><a href="https://mermaid.live/edit#pako:eNqdU8tuwjAQ_JWVTyAeElcqkCj1oRIKrVM4VYqWeEMtEps6DlKF-PeaJm5oERdyiJTJzOzsen1kqZHExsBK-qxIp_SkcGuxeHjX4J89WqdStUftQFBK6kD2-k9MWgY8Mo7AeNovfwwLdFQ6sDUgIdQCVYKuZbXFYDptVfOVEDx6S_j6_I7564pHc94J4knRraVB4cW1yxjEmRw30k6mbOmSX53ujfqQ4yUUrNrwwYkfSDufsjcCZ2A3GIE2kBu99ZxNlWVkSd7sQPD4ZRnFvGmBC7EUnb85wldiculnlOABVY6bnCa7vh8YlkZPVtFsPXtezB4XvHuz1nA4vDOHb-reHBejb6tdjwwt-ZmV7mbA-pzaRPe1-c-l6LI-sIJsgUr6FT8y90HFz7JLyrDKHTt5AlbOxF869bizFXmk2ku_sM1FaODTNxaaDY8" target="_blank" rel="noreferrer"><img src="https://mermaid.ink/img/pako:eNqdU8tuwjAQ_JWVTyAeElcqkCj1oRIKrVM4VYqWeEMtEps6DlKF-PeaJm5oERdyiJTJzOzsen1kqZHExsBK-qxIp_SkcGuxeHjX4J89WqdStUftQFBK6kD2-k9MWgY8Mo7AeNovfwwLdFQ6sDUgIdQCVYKuZbXFYDptVfOVEDx6S_j6_I7564pHc94J4knRraVB4cW1yxjEmRw30k6mbOmSX53ujfqQ4yUUrNrwwYkfSDufsjcCZ2A3GIE2kBu99ZxNlWVkSd7sQPD4ZRnFvGmBC7EUnb85wldiculnlOABVY6bnCa7vh8YlkZPVtFsPXtezB4XvHuz1nA4vDOHb-reHBejb6tdjwwt-ZmV7mbA-pzaRPe1-c-l6LI-sIJsgUr6FT8y90HFz7JLyrDKHTt5AlbOxF869bizFXmk2ku_sM1FaODTNxaaDY8" alt="Mermaid Sequence: Requested events unavailable"></a></p><h2 id="events-sub-protocols" tabindex="-1">Events Sub-Protocols <a class="header-anchor" href="#events-sub-protocols" aria-label="Permalink to &quot;Events Sub-Protocols&quot;">​</a></h2><p>Sub-protocols can be layered over the events protocol in order to manage how certain types of events are presented and handled. A sub-protocol defines:</p><ul><li>The event groups that it uses.</li><li>The meaning of particular event types within those groups (such as <code>summary</code>), and the order in which events are sent.</li><li>Any required event arguments or constraints (for example enums that a component must define in its events metadata).</li></ul><p>A component indicates that it supports a sub-protocol by listing it in the <code>supported_protocols</code> of its events metadata. A receiver should only use a sub-protocol if the sender lists it, and can ignore events in the groups of sub-protocols that it does not implement.</p><p>Only the health and arming checks sub-protocol is currently implemented.</p><h3 id="health-and-arming-checks" tabindex="-1">Health and Arming Checks <a class="header-anchor" href="#health-and-arming-checks" aria-label="Permalink to &quot;Health and Arming Checks&quot;">​</a></h3><p>The events interface is used to report the health of vehicle subsystems and the results of arming checks. A GCS can use this report to show the state of each subsystem (for example, a GPS indicator), to enable UI actions such as arming or starting a mission, and to list the problems that need to be fixed (with a detailed explanation for each).</p><p>Health problems are those that require maintenance or repair of the vehicle, such as a failed sensor. Arming check problems are conditions that prevent arming, and which can usually be fixed in the field, such as having no GPS fix or requiring sensor calibration.</p><p>A component that supports this sub-protocol lists <code>health_and_arming_check</code> in the <code>supported_protocols</code> of its events metadata. The metadata also defines two bitmask enums that are used by the report:</p><ul><li>Health components: one bit for each subsystem or sensor. The first bit must be &quot;none&quot;.</li><li>Navigation mode groups: one bit for each group of flight modes that share the same arming checks. The metadata <code>navigation_mode_groups</code> maps each group to the MAVLink custom modes that it contains.</li></ul><p>A report consists of the following events, sent in order:</p><ol><li>Arming check summary (group <code>arming_check</code>, type <code>summary</code>), with arguments: <ul><li><code>chunk_idx</code>: Index of the chunk (a report can be split into multiple chunks that the receiver combines).</li><li><code>error</code>, <code>warning</code>: Health components that have arming check errors or warnings.</li><li><code>can_arm</code>: Navigation mode groups in which the vehicle can be armed.</li><li><code>can_run</code>: Navigation mode groups that the vehicle can switch to while armed.</li></ul></li><li>Zero or more events for individual problems (group <code>health</code> or <code>arming_check</code>). The first two arguments of each event are: <ul><li>The navigation mode groups that are affected by the problem (bitmask).</li><li>The index of the affected health component (0 if none applies).</li></ul></li><li>Health summary (group <code>health</code>, type <code>summary</code>), with arguments: <ul><li><code>chunk_idx</code>: Index of the chunk.</li><li><code>is_present</code>, <code>error</code>, <code>warning</code>: Health components that are present, that have errors, and that have warnings.</li></ul></li></ol><p>The sender sends a new report whenever the results change, and when it receives <a href="./../messages/common.html#MAV_CMD_RUN_PREARM_CHECKS">MAV_CMD_RUN_PREARM_CHECKS</a>. A receiver replaces its current report when it receives a complete new report, and should discard a partial report if events are lost.</p><p><a href="https://mermaid.live/edit#pako:eNqlkl1LwzAUhv_KIVcTtODtxEFJg8JsHd3HlVBielyDTRPTxDHG_rvHbQ7GmAjmLm_e5-V8ZMOUrZENgfX4EbFTmGm59NLcvXRAx0kftNJOdgEe-PRcTGOwTrc27J_IczMaHcUh5Omi4nlWlfOimpQiLfOKPwo-PkQdnUQROwT-nOdpkVUpHw889rEN998RpZjOn2akcjGZiezqAi0WopgNpDe6W4JqUL1DH42Rfv070aBsQwPWwwnrvH1t0cDtJTpJkv_kFn-q6rSD_YR3rhJdKxVSHH5qG3vw6KwPsNJEdbg63Nk1MIPeSF3TojcsNGh2K6_xTdKA2ZYMkkqYrjtFevARSYmuluHnOxzk7Rfljba3" target="_blank" rel="noreferrer"><img src="https://mermaid.ink/img/pako:eNqlkl1LwzAUhv_KIVcTtODtxEFJg8JsHd3HlVBielyDTRPTxDHG_rvHbQ7GmAjmLm_e5-V8ZMOUrZENgfX4EbFTmGm59NLcvXRAx0kftNJOdgEe-PRcTGOwTrc27J_IczMaHcUh5Omi4nlWlfOimpQiLfOKPwo-PkQdnUQROwT-nOdpkVUpHw889rEN998RpZjOn2akcjGZiezqAi0WopgNpDe6W4JqUL1DH42Rfv070aBsQwPWwwnrvH1t0cDtJTpJkv_kFn-q6rSD_YR3rhJdKxVSHH5qG3vw6KwPsNJEdbg63Nk1MIPeSF3TojcsNGh2K6_xTdKA2ZYMkkqYrjtFevARSYmuluHnOxzk7Rfljba3" alt="Mermaid Sequence: Health and arming checks"></a></p><p>Events of type <code>append_health_and_arming_messages</code> take a custom mode as their first argument. A GCS displays the message of such an event followed by the current problems for that mode (for example, to explain why arming or a mode switch was denied).</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Event arguments cannot be strings, arrays, or <code>double</code> values.</li><li>A receiver cannot display an event for which it does not have metadata (only the event ID is known).</li><li>A sender does not know whether or when an event has been received.</li></ul><h2 id="implementations" tabindex="-1">Implementations <a class="header-anchor" href="#implementations" aria-label="Permalink to &quot;Implementations&quot;">​</a></h2><p>Implementation PRs and other information is listed below.</p><ul><li><a href="https://github.com/mavlink/libevents" target="_blank" rel="noreferrer">libevents</a>: C++ and Python library for receiving events, parsing events with their metadata, and handling health and arming check reports. It also contains the common event definitions and the metadata schema. <ul><li>The libevents tooling limits event arguments to 25 bytes (to reduce sender buffer requirements), which is less than the 40 bytes allowed by <code>EVENT</code> (<a href="https://github.com/mavlink/libevents/blob/main/config.ini" target="_blank" rel="noreferrer">config.ini</a>).</li><li><a href="https://github.com/mavlink/libevents/blob/main/libs/cpp/protocol/receive.h" target="_blank" rel="noreferrer">receive.h</a> implements the receiving side of the protocol. It requests one event at a time (<code>first_sequence</code> equal to <code>last_sequence</code>), re-requests after a timeout of 100 ms, and discards an event that arrives out of order (the event is re-requested later). It also treats a large backwards jump in <code>event_time_boot_ms</code> as a sender reboot, in case the reset flag was missed.</li><li><a href="https://github.com/mavlink/libevents/blob/main/libs/cpp/parse/health_and_arming_checks.h" target="_blank" rel="noreferrer">health_and_arming_checks.h</a> implements the receiving side of the health and arming checks report.</li></ul></li><li>QGroundControl <ul><li>PR: <a href="https://github.com/mavlink/qgroundcontrol/pull/9217" target="_blank" rel="noreferrer">Events interface (first iteration) #9217</a></li><li>Source: <a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/MAVLink/LibEvents" target="_blank" rel="noreferrer">src/MAVLink/LibEvents</a></li><li>QGroundControl sends <code>MAV_CMD_RUN_PREARM_CHECKS</code> after it has loaded the events metadata for the vehicle, in order to get a health and arming checks report (<a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/Vehicle/Vehicle.cc" target="_blank" rel="noreferrer">Vehicle.cc</a>).</li></ul></li><li>PX4: <ul><li><a href="https://docs.px4.io/main/en/concept/events_interface.html" target="_blank" rel="noreferrer">Events Interface</a> (docs)</li><li>PR: <a href="https://github.com/PX4/PX4-Autopilot/pull/16293" target="_blank" rel="noreferrer">Events interface #16293</a></li><li>Source: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_events.cpp" target="_blank" rel="noreferrer">src/modules/mavlink/mavlink_events.cpp</a></li><li>PX4 buffers the 20 most recent events, and sends <code>CURRENT_EVENT_SEQUENCE</code> every 3 seconds (<a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_events.h" target="_blank" rel="noreferrer">mavlink_events.h</a>, <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_events.cpp" target="_blank" rel="noreferrer">mavlink_events.cpp</a>).</li><li>PX4 sends a health and arming checks report when the results change and when it receives <code>MAV_CMD_RUN_PREARM_CHECKS</code> (<a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/commander/Commander.cpp" target="_blank" rel="noreferrer">Commander.cpp</a>, <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/commander/HealthAndArmingChecks/Common.cpp" target="_blank" rel="noreferrer">HealthAndArmingChecks/Common.cpp</a>).</li><li>PX4 also sends each event as a <code>STATUSTEXT</code> that ends with a tab character, for GCSs that do not support events. QGroundControl ignores these messages from PX4 (<a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/Vehicle/Vehicle.cc" target="_blank" rel="noreferrer">Vehicle.cc</a>).</li><li>MAVSDK <a href="https://github.com/mavlink/MAVSDK/tree/main/cpp/src/mavsdk/plugins/events" target="_blank" rel="noreferrer">events plugin</a></li></ul></li></ul>',59)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
